import math
t = int(input())
for i in range(t):
	a = [int(x) for x in input().split()]
	n = a[0]
	op = a[1]
	x = a[2]
	y = a[3]
	z = a[4]
	n1 = n * 2 + 1
	if op == 1:
		if x < y and y < z:
			m = n1 - z
		elif x > y and y > z:
			m = n1 - z
		else:
			m = x
	elif op == 2:
		m = n1 - (z + x)
	elif op == 3:
		if x > y and y > z:
			m = n1 - x
		elif x < y and y < z:
			m = n1 - x
		else:
			m = x
	elif op == 4:
		m = n1 - (z + x)
	gc = math.gcd(m, n1)
	m2 = int(m / gc)
	n2 = int(n1 / gc)
	print(m2, end=' ')
	print(n2)
